// Una proposta per ogni sessione bloccante (non una per ogni sessione bloccata).
const gruppi = {};
for (const { json: r } of $input.all()) {
  const g = gruppi[r.pid_bloccante] ??= {
    pid_bloccante: r.pid_bloccante,
    utente_bloccante: r.utente_bloccante,
    ip_bloccante: r.ip_bloccante ?? 'locale (socket)',
    applicazione_bloccante: r.applicazione_bloccante || null,
    stato_bloccante: r.stato_bloccante,
    query_bloccante: r.query_bloccante,
    durata_tx_bloccante_sec: r.durata_tx_bloccante_sec,
    attesa_max_sec: 0,
    bloccate: [],
  };
  g.bloccate.push({ pid: r.pid_bloccato, utente: r.utente_bloccato, ip: r.ip_bloccato ?? 'locale (socket)', query: r.query_bloccata, attesa_sec: r.attesa_sec });
  g.attesa_max_sec = Math.max(g.attesa_max_sec, r.attesa_sec);
}

return Object.values(gruppi).map(g => ({
  json: {
    ...g,
    n_bloccate: g.bloccate.length,
    domanda: `Lock su PostgreSQL: attesa massima ${g.attesa_max_sec} secondi, sessioni bloccate ${g.bloccate.length}. Quale severità assegnare?`,
  },
}));

// Valida la risposta di Ollama: se non è JSON valido si ripiega su valori prudenti.
const { domanda, ...s } = $('Raggruppa per bloccante').item.json;
const kb = $('Componi prompt').item.json;

let p = {};
try { p = JSON.parse($json.response); } catch (e) { p = {}; }

// La severità fa fede dal vector DB; se il modello ne riporta una diversa lo si annota nel dettaglio.
const severity_modello = ['P1', 'P2', 'P3', 'P4'].includes(p.severity) ? p.severity : null;
const severity = kb.severita_kb ?? severity_modello ?? 'P3';
const azione = p.azione === 'TERMINA' ? 'TERMINA' : 'ATTENDI';
const motivazione = String(p.motivazione || 'risposta del modello non interpretabile').slice(0, 300);

// Telegram interpreta il testo come Markdown: i caratteri _ * ` [ vanno preceduti da \
// altrimenti nomi come app_user fanno fallire l'invio ("can't parse entities").
const esc = v => String(v ?? '').replace(/([_*`\[])/g, '\\$1');
const messaggio = [
  `🚨 Lock su labdb — severità ${severity}`,
  '',
  `Bloccante: pid ${s.pid_bloccante} (${esc(s.stato_bloccante)}), transazione aperta da ${s.durata_tx_bloccante_sec} s`,
  `Utente: ${esc(s.utente_bloccante)}`,
  `IP di provenienza: ${esc(s.ip_bloccante)}` + (s.applicazione_bloccante ? ` (${esc(s.applicazione_bloccante)})` : ''),
  `Query: ${esc(s.query_bloccante)}`,
  '',
  `Sessioni bloccate: ${s.n_bloccate} (attesa massima ${s.attesa_max_sec} s)`,
  ...s.bloccate.slice(0, 5).map(b => `• pid ${b.pid}, utente ${esc(b.utente)}, IP ${esc(b.ip)}, in attesa da ${b.attesa_sec} s`),
  '',
  `Proposta AI: ${azione}`,
  esc(motivazione),
  '',
  'Approva = termina la sessione bloccante.',
].join('\n');

return {
  json: {
    ...s,
    messaggio,
    severity,
    azione,
    motivazione,
    target: `pid=${s.pid_bloccante}`,
    detail: {
      modello: $('Config').first().json.modello,
      azione_proposta: azione,
      severita_kb: kb.severita_kb,
      severita_modello: severity_modello,
      criterio_kb: kb.criterio_kb,
      motivazione,
      bloccante: { pid: s.pid_bloccante, utente: s.utente_bloccante, ip: s.ip_bloccante, applicazione: s.applicazione_bloccante, stato: s.stato_bloccante, query: s.query_bloccante, durata_tx_sec: s.durata_tx_bloccante_sec },
      bloccate: s.bloccate,
    },
  },
};

// Compone il prompt con ciò che è stato recuperato dalla base vettoriale.
const g = $('Raggruppa per bloccante').item.json;
const kb = $json;

const prompt = `Sei un DBA PostgreSQL che fa triage di lock. Usa SOLO quanto riportato dalla base di conoscenza.

SITUAZIONE
- sessione bloccante: pid ${g.pid_bloccante}, utente ${g.utente_bloccante}, stato ${g.stato_bloccante}, transazione aperta da ${g.durata_tx_bloccante_sec} secondi
- query bloccante: ${g.query_bloccante}
- sessioni bloccate: ${g.n_bloccate}
- attesa massima: ${g.attesa_max_sec} secondi

BASE DI CONOSCENZA
Criterio applicabile a questa situazione: severità ${kb.severita_kb}
${kb.criterio_kb}

${kb.contesto_kb ?? ''}

Rispondi SOLO con un oggetto JSON:
{"severity": "la severità indicata dal criterio applicabile", "azione": "TERMINA|ATTENDI secondo il criterio", "motivazione": "una frase in italiano che cita attesa massima e numero di sessioni bloccate"}`;

return { json: { severita_kb: kb.severita_kb, criterio_kb: kb.criterio_kb, prompt } };
